BEGIN;
SET LOCAL lock_timeout = '1s';
SET LOCAL statement_timeout = '5s';
LOCK TABLE public.fhfh_player_identity_aliases, public.lineup_player_name_aliases IN SHARE ROW EXCLUSIVE MODE;
DO $owner_nickname_guard$
DECLARE target_id bigint;
BEGIN
 SELECT id INTO STRICT target_id
 FROM public.fhfh_player_identities
 WHERE id = 9521 AND nhl_player_id = 8476454
   AND canonical_name = 'Ryan Nugent-Hopkins' AND verification_status = 'verified'
 FOR SHARE;
 IF EXISTS (
   SELECT 1 FROM public.fhfh_player_identity_aliases
   WHERE lower(regexp_replace(alias, '[.[:space:]]', '', 'g')) = 'rnh'
      OR lower(regexp_replace(normalized_alias, '[.[:space:]]', '', 'g')) = 'rnh'
 ) OR EXISTS (
   SELECT 1 FROM public.lineup_player_name_aliases
   WHERE lower(regexp_replace(alias, '[.[:space:]]', '', 'g')) = 'rnh'
      OR lower(regexp_replace(normalized_alias, '[.[:space:]]', '', 'g')) = 'rnh'
 ) THEN
   RAISE EXCEPTION 'RNH alias appeared; stop without overwrite and inspect existing mapping';
 END IF;
END;
$owner_nickname_guard$;
INSERT INTO public.fhfh_player_identity_aliases
 (fhfh_player_id, alias, normalized_alias, source, verification_status, source_provenance)
VALUES
 (9521, 'RNH', public.immutable_unaccent(lower(btrim('RNH'))), 'manual', 'verified',
 jsonb_build_object(
   'schema_version', 1,
   'evidence_type', 'owner_confirmation',
   'alias_kind', 'nickname',
   'confirmed_by', 'TJ',
   'confirmed_at', '2026-10-20T23:03:35Z',
   'confirmation', 'RNH → can confidently be stored in the nickname library, mapping to Ryan Nugent-Hopkins.',
   'nhl_player_id', 8476454,
   'scope', 'global_identity_only',
   'historical_team_membership_asserted', false,
   'model_confidence_used_as_verification', false
 ));
COMMIT;
SELECT a.id, a.fhfh_player_id, i.nhl_player_id, i.canonical_name, a.alias,
 a.normalized_alias, a.source, a.verification_status, a.source_provenance, a.created_at
FROM public.fhfh_player_identity_aliases a
JOIN public.fhfh_player_identities i ON i.id = a.fhfh_player_id
WHERE a.fhfh_player_id = 9521 AND a.normalized_alias = 'rnh'
ORDER BY a.id LIMIT 5;
